                                    ]"
                                    (click)="selectCategory(item.label)"
                                >
                                    <i [class]="item.icon" class="text-xs"></i>
                                    <span class="flex-1 text-base font-medium">{{ item.label }}</span>
                                    @if (item.count && item.count > 0) {
                                        <div
                                            [ngClass]="[
