                <!-- Table -->
                <div class="flex-1 flex flex-col min-h-0">
                    <p-table [value]="paginatedEmails()" [(selection)]="selectedEmails" dataKey="id" [paginator]="false" styleClass="mail-table" [scrollable]="true" scrollHeight="flex">
                        <ng-template #header>
                            <tr>
                                <th style="width: 3rem">
                                    <p-tableHeaderCheckbox />
